Section Segs.
Variable rom : word -> option byte.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Definition ge_fp (fr fr' : bvmap 5 word) : Prop :=
  forall r : reg, r <> 11%bv -> r <> 12%bv -> r <> 13%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r.
(* [comment removed for export] *)
Definition GML : list reg := [19; 23; 24; 25; 26]%bv.
Definition GKL : list reg := [6; 19; 21; 22; 23; 24; 25; 26; 31]%bv.
Definition GJL : list reg := [5; 6; 7; 15; 17; 19; 21; 22; 23; 24; 25; 26; 28; 29; 30; 31]%bv.
Definition GIL : list reg := [5; 6; 7; 12; 14; 15; 16; 17; 19; 21; 22; 23; 24; 25; 26; 28; 29; 30; 31]%bv.
Definition GNL : list reg := [5; 6; 7; 11; 12; 13; 14; 15; 16; 17; 19; 21; 22; 23; 24; 25; 26; 28; 29; 30; 31]%bv.

(* [comment removed for export] *)
Lemma gm_loop : forall (n : nat) fr0 regs0 fr cs regs (M : word -> option byte) (Wt krow rrow cval rb col m : Z),
  Z.of_nat n = (41 - m)%Z -> (0 <= m <= 40)%Z -> frm_zero cs ->
  (rb mod 4 = 0)%Z -> (Wt mod 4 = 0)%Z -> (4096 <= rb)%Z -> (rb + Wt <= 2 ^ 47)%Z -> (0 <= col)%Z -> (col + 40 < Wt)%Z ->
  (4096 <= krow)%Z -> (krow + 164 <= 2 ^ 47)%Z -> (4096 <= rrow)%Z -> (rrow + 1024 <= 2 ^ 47)%Z -> (0 <= cval <= 255)%Z ->
  (forall p, (rb <= p < rb + Wt)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) ->
  (forall q, (0 <= q <= 40)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (krow + 4 * q)) 4 = Some bs) ->
  (forall d, (0 <= d <= 255)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rrow + 4 * d)) 4 = Some bs) ->
  getr regs 23 = Z_to_bv 64 (rb + col + m) -> getr regs 22 = Z_to_bv 64 (rb + col + 41) -> getr regs 19 = Z_to_bv 64 (krow + 4 * m) ->
  getr regs 21 = Z_to_bv 64 rrow -> getr regs 7 = Z_to_bv 64 cval ->
  regs_agree (fun r => In r GML) regs0 regs -> ge_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e8d8 : word) M rom)
    (fun fin => exists fr' cs' regs', fin = @mkst (mkFP fr' cs') regs' (0x2e91c : word) M rom /\ frm_zero cs' /\
