(* [comment removed for export] *)
Definition ge_rd (M : word -> option byte) (sf w h Wt hs datat keli arrk rng arrr rrow : Z) (rowk : Z -> Z) : Prop :=
  rdn SEGS M (Z_to_bv 64 (sf + 8)) 8 = Some (Z_to_le_bytes 8 keli) /\
  rdn SEGS M (Z_to_bv 64 (sf + 20)) 4 = Some (Z_to_le_bytes 4 20) /\ rdn SEGS M (Z_to_bv 64 (sf + 24)) 4 = Some (Z_to_le_bytes 4 20) /\
  rdn SEGS M (Z_to_bv 64 (sf + 28)) 4 = Some (Z_to_le_bytes 4 41) /\ rdn SEGS M (Z_to_bv 64 (sf + 32)) 4 = Some (Z_to_le_bytes 4 41) /\
  rdn SEGS M (Z_to_bv 64 (sf + 40)) 4 = Some (Z_to_le_bytes 4 h) /\ rdn SEGS M (Z_to_bv 64 (sf + 44)) 4 = Some (Z_to_le_bytes 4 w) /\
  (forall p, (datat <= p < datat + Wt * hs)%Z -> exists b, rdn SEGS M (Z_to_bv 64 p) 1 = Some [b]) /\
  rdn SEGS M (Z_to_bv 64 (keli + 16)) 8 = Some (Z_to_le_bytes 8 arrk) /\
  (forall q, (0 <= q < 41)%Z -> rdn SEGS M (Z_to_bv 64 (arrk + 8 * q)) 8 = Some (Z_to_le_bytes 8 (rowk q)) /\ (4096 <= rowk q)%Z /\ (rowk q + 164 <= 2 ^ 47)%Z) /\
  (forall q t, (0 <= q < 41)%Z -> (0 <= t <= 40)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rowk q + 4 * t)) 4 = Some bs) /\
  rdn SEGS M (Z_to_bv 64 (rng + 16)) 8 = Some (Z_to_le_bytes 8 arrr) /\ rdn SEGS M (Z_to_bv 64 arrr) 8 = Some (Z_to_le_bytes 8 rrow) /\
  (forall d, (0 <= d <= 255)%Z -> exists bs, rdn SEGS M (Z_to_bv 64 (rrow + 4 * d)) 4 = Some bs).

(* [comment removed for export] *)
Definition ge_geo (sf w h wplt Wt hs wpld Wd datat datad keli arrk rng arrr rrow : Z) : Prop :=
  (4096 <= sf)%Z /\ (sf + 144 <= 2 ^ 47)%Z /\ (1 <= w <= 20000)%Z /\ (1 <= h <= 20000)%Z /\ (hs = h + 41)%Z /\
  (0 <= wplt)%Z /\ (Wt = 4 * wplt)%Z /\ (w + 41 <= Wt)%Z /\ (Wt * hs <= 2 ^ 26)%Z /\
  (0 <= wpld)%Z /\ (Wd = 4 * wpld)%Z /\ (w <= Wd)%Z /\ (Wd * h <= 2 ^ 26)%Z /\
  (datat mod 4 = 0)%Z /\ (4096 <= datat)%Z /\ (datat + Wt * hs <= 2 ^ 47)%Z /\
  (datad mod 4 = 0)%Z /\ (4096 <= datad)%Z /\ (datad + Wd * h <= 2 ^ 47)%Z /\ (datad + Wd * h <= sf \/ sf + 144 <= datad)%Z /\
  (4096 <= keli)%Z /\ (keli + 24 <= 2 ^ 47)%Z /\ (4096 <= arrk)%Z /\ (arrk + 328 <= 2 ^ 47)%Z /\
  (4096 <= rng)%Z /\ (rng + 24 <= 2 ^ 47)%Z /\ (4096 <= arrr)%Z /\ (arrr + 8 <= 2 ^ 47)%Z /\ (4096 <= rrow)%Z /\ (rrow + 1024 <= 2 ^ 47)%Z.

Definition GJB : list reg := [5; 6; 7; 19; 21; 22; 23; 24; 25; 26; 28; 29; 30; 31]%bv.

(* [comment removed for export] *)
Lemma gj_body : forall fr0 regs0 fr cs regs (M0 M : word -> option byte) (sf w h wplt Wt hs wpld Wd datat datad keli arrk rng arrr rrow i j : Z) (rowk : Z -> Z),
  frm_zero cs -> ge_geo sf w h wplt Wt hs wpld Wd datat datad keli arrk rng arrr rrow ->
  (forall M', rinv [(datad, (Wd * h)%Z)] M0 M' -> ge_rd M' sf w h Wt hs datat keli arrk rng arrr rrow rowk) ->
  store_ok SEGS M0 (Z_to_bv 64 datad) (Z.to_nat (Wd * h)) = true -> rinv [(datad, (Wd * h)%Z)] M0 M ->
  (0 <= i < h)%Z -> (0 <= j < w)%Z ->
  getr regs 2 = Z_to_bv 64 sf -> getr regs 15 = Z_to_bv 64 j -> getr regs 17 = Z_to_bv 64 (datat + Wt * i + j) -> getr regs 16 = Z_to_bv 64 (datad + Wd * i) ->
  getr regs 12 = Z_to_bv 64 i -> getr regs 13 = Z_to_bv 64 Wt -> getr regs 11 = Z_to_bv 64 rng -> getr regs 8 = Z_to_bv 64 datat -> getr regs 18 = Z_to_bv 64 wplt ->
  regs_agree (fun r => In r GJB) regs0 regs -> ge_fp fr0 fr ->
  reach SEGS (@mkst (mkFP fr cs) regs (0x2e850 : word) M rom)
    (fun fin => exists fr' cs' regs' M', fin = @mkst (mkFP fr' cs') regs' (0x2e840 : word) M' rom /\ frm_zero cs' /\
                (exists p bs, (datad <= p < datad + Wd * h)%Z /\ length bs = 1%nat /\ M' = wbytes M (Z_to_bv 64 p) bs) /\
