  (forall M', rinv [(datad, (Wd * h)%Z)] M0 M' -> ge_rd M' sf w h Wt hs datat keli arrk rng arrr rrow rowk) ->
  store_ok SEGS M0 (Z_to_bv 64 datad) (Z.to_nat (Wd * h)) = true -> rinv [(datad, (Wd * h)%Z)] M0 M ->
